import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    if k > n * n // 2:
        print(-1)
        return

    matrix = [[0] * n for _ in range(n)]

    ones_placed = 0
    for i in range(n):
        for j in range(i, n):
            if ones_placed < k:
                matrix[i][j] = 1
                matrix[j][i] = 1
                ones_placed += 1

    for row in matrix:
        print(" ".join(map(str, row)))

if __name__ == "__main__":
    main()
